// Build Report: validate the inputs, then build the report from calculated values only.
const kpi = $('Get KPIs').first().json;
const exceptions = $('Get Exceptions').all().map(item => item.json);

// 1. Required KPI fields must exist and be numbers (Postgres sends them as text)
const kpiFields = [
  'total_orders', 'total_order_value', 'excluded_canceled_orders',
  'eligible_orders', 'on_time_orders', 'late_orders',
  'on_time_pct', 'delay_rate_pct', 'avg_order_to_ship_days',
];
const badKpi = kpiFields.filter(f =>
  kpi[f] === undefined || kpi[f] === null || kpi[f] === '' || Number.isNaN(Number(kpi[f]))
);
if (badKpi.length > 0) {
  throw new Error('KPI validation failed. Missing or non-numeric fields: ' + badKpi.join(', '));
}
const k = {};
kpiFields.forEach(f => { k[f] = Number(kpi[f]); });

// 2. The numbers must agree with each other
const problems = [];
if (k.eligible_orders + k.excluded_canceled_orders !== k.total_orders) {
  problems.push('eligible + excluded does not equal total orders');
}
if (k.on_time_orders + k.late_orders !== k.eligible_orders) {
  problems.push('on-time + late does not equal eligible orders');
}
if (k.eligible_orders <= 0) {
  problems.push('eligible orders must be above zero');
} else {
  const delayCheck = Math.round(10000 * k.late_orders / k.eligible_orders) / 100;
  if (Math.abs(delayCheck - k.delay_rate_pct) > 0.01) {
    problems.push('delay rate does not match late / eligible');
  }
}

// 3. Every exception row needs its fields
const exFields = ['shipping_mode', 'eligible_orders', 'late_orders', 'delay_rate_pct', 'points_above_overall'];
exceptions.forEach((row, i) => {
  const missing = exFields.filter(f => row[f] === undefined || row[f] === null || row[f] === '');
  if (missing.length > 0) {
    problems.push('exception row ' + (i + 1) + ' is missing: ' + missing.join(', '));
  }
});
if (problems.length > 0) {
  throw new Error('Validation failed: ' + problems.join('; '));
}

// 4. Build the report text
const n0 = v => Number(v).toLocaleString('en-US');
const n2 = v => Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const lines = [
  'KPI REPORT',
  'Generated (UTC): ' + new Date().toISOString(),
  'Sources: analytics.kpi_summary, analytics.exceptions_shipping_mode',
  '',
  'SUMMARY',
  'Total orders: ' + n0(k.total_orders),
  'Total order value: ' + n2(k.total_order_value),
  'Eligible orders: ' + n0(k.eligible_orders) + ' (excludes ' + n0(k.excluded_canceled_orders) + ' canceled orders)',
  'On-time: ' + n0(k.on_time_orders) + ' (' + n2(k.on_time_pct) + '%)',
  'Late: ' + n0(k.late_orders) + ' (' + n2(k.delay_rate_pct) + '%)',
  'Average order-to-ship days: ' + n2(k.avg_order_to_ship_days),
  '',
  'EXCEPTIONS (delay rate above overall ' + n2(k.delay_rate_pct) + '%, at least 500 eligible orders)',
];
if (exceptions.length === 0) {
  lines.push('No exceptions found.');
} else {
  exceptions.forEach(e => {
    lines.push('- ' + e.shipping_mode + ': ' + n0(e.late_orders) + ' late of ' + n0(e.eligible_orders) +
      ' eligible (' + n2(e.delay_rate_pct) + '%, +' + n2(e.points_above_overall) + ' points)');
  });
}

return [{ json: { validation: 'passed', kpis: k, exceptions, report_text: lines.join('\n') } }];
